steps.body:
A **discriminated union** is a union of object types that share one property, the tag, with a different literal type in each member. `kind` is the usual name for it, and `type` and `status` are common too. Checking the tag narrows the value to one member, so that member's own fields become usable:

```typescript
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

function area(shape: Shape): number {
  if (shape.kind === "circle") {
    return Math.PI * shape.radius ** 2;
    //               ^? (parameter) shape: { kind: "circle"; radius: number; }
  }
  return shape.side ** 2;
  //     ^? (parameter) shape: { kind: "square"; side: number; }
}

console.log(area({ kind: "square", side: 3 })); // 9
```

Before the check, the tag is the only field every member has, so reading `shape.radius` there is a type error. A `switch` on the tag narrows the same way in each `case`, and it reads better once a union has three or more members. A tag also works when two members have the same fields, where an `in` check can't tell them apart.

examples.code:
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "rect":
      return shape.width * shape.height;
  }
}

const shapes: Shape[] = [
  { kind: "circle", radius: 2 },
  { kind: "rect", width: 3, height: 4 },
  { kind: "circle", radius: 0.5 },
];

for (const shape of shapes) {
  console.log(`${shape.kind}: ${area(shape).toFixed(2)}`);
}

type Payment =
  | { kind: "card"; last4: string }
  | { kind: "paypal"; email: string }
  | { kind: "bank"; iban: string };

function receiptLine(payment: Payment): string {
  switch (payment.kind) {
    case "card":
      return `Paid by card ending ${payment.last4}`;
    case "paypal":
      return `Paid with PayPal (${payment.email})`;
    case "bank":
      return `Paid by bank transfer from ${payment.iban.slice(0, 4)}...${payment.iban.slice(-4)}`;
  }
}

const payments: Payment[] = [
  { kind: "card", last4: "4242" },
  { kind: "paypal", email: "ada@example.com" },
  { kind: "bank", iban: "GB33BUKB20201555555555" },
];

for (const payment of payments) {
  console.log(receiptLine(payment));
}

type User = { id: number; name: string };

type UserResult =
  | { ok: true; data: User }
  | { ok: false; error: string };

const results: UserResult[] = [
  { ok: true, data: { id: 1, name: "Ada" } },
  { ok: false, error: "user 7 not found" },
  { ok: true, data: { id: 2, name: "Grace" } },
];

for (const result of results) {
  if (result.ok) {
    console.log(`Loaded ${result.data.name} (#${result.data.id})`);
  } else {
    console.log(`Failed: ${result.error}`);
  }
}

