export type Notification =
  | { kind: "email"; to: string; subject: string }
  | { kind: "sms"; phone: string; text: string }
  | { kind: "push"; deviceId: string; title: string };

export function describe(n: Notification): string {
  switch (n.kind) {
    case "email":
      return `Email to ${n.to}: ${n.subject}`;
    case "sms":
      return `SMS to ${n.phone}: ${n.text}`;
    case "push":
      return `Push to ${n.deviceId}: ${n.title}`;
  }
}

const inbox: Notification[] = [
  { kind: "email", to: "ada@example.com", subject: "Your order shipped" },
  { kind: "sms", phone: "+44 7700 900123", text: "Code 481516" },
  { kind: "push", deviceId: "pixel-7", title: "Back in stock" },
];

for (const n of inbox) {
  console.log(describe(n));
}

steps.body:
A `switch` that handles every member is complete today. The trouble comes later, when someone adds a member to the union and every `switch` that doesn't know about it quietly misses a case. You can make the checker find those for you. Once every case is handled, the value that reaches `default` has the type `never`, so you can pass it to a helper that only takes `never`:

```typescript
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`);
}

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.side ** 2;
    default:
      return assertNever(shape);
      //                 ^? (parameter) shape: never
  }
}

console.log(area({ kind: "square", side: 3 })); // 9
```

Add a member and forget its case, and the value in `default` is that new member, which isn't assignable to `never`. The call to `assertNever` stops compiling with TS2345, in every `switch` that needs the new case. Assigning to a variable works the same way: `const unreachable: never = shape` fails with TS2322. The `throw` covers values the checker never saw, such as JSON from a newer server.

examples.code:
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "rect":
      return shape.width * shape.height;
    default: {
      const unreachable: never = shape;
      throw new Error(`Unknown shape: ${JSON.stringify(unreachable)}`);
    }
  }
}

console.log(area({ kind: "circle", radius: 1 }).toFixed(2));
console.log(area({ kind: "rect", width: 2, height: 5 }));

examples.explanation:
Both kinds have a case, so `shape` is `never` in `default` and the assignment compiles. The program runs, and the `throw` never happens. Now add a triangle to the union and nothing else:

```typescript error
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number }
  | { kind: "triangle"; base: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "rect":
      return shape.width * shape.height;
    default: {
      const unreachable: never = shape;
      throw new Error(`Unknown shape: ${JSON.stringify(unreachable)}`);
    }
  }
}

console.log(area({ kind: "triangle", base: 6, height: 2 }));
```

The triangle reaches `default`, and the checker stops on the assignment: `Type '{ kind: "triangle"; base: number; height: number; }' is not assignable to type 'never'.` Add a `case "triangle"` that returns `shape.base * shape.height / 2`, and it compiles again.

examples.code:
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number };

function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`);
}

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "rect":
      return shape.width * shape.height;
    default:
      return assertNever(shape);
  }
}

// JSON.parse returns any, so the checker trusts this data blindly.
const shapes: Shape[] = JSON.parse('[{"kind":"rect","width":2,"height":5},{"kind":"hexagon","side":1}]');

for (const shape of shapes) {
  try {
    console.log(`${shape.kind}: ${area(shape)}`);
  } catch (err) {
    console.log(err instanceof Error ? err.message : String(err));
  }
}

type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number }
  | { kind: "triangle"; base: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "rect":
      return shape.width * shape.height;
    default:
      return 0;
  }
}

const shapes: Shape[] = [
  { kind: "rect", width: 3, height: 4 },
  { kind: "triangle", base: 6, height: 2 },
];

for (const shape of shapes) {
  console.log(`${shape.kind}: ${area(shape)}`);
}

