steps.body:
Put each field only on the states where it exists. A shipped order has a tracking number and a pending order doesn't, so `trackingNumber` belongs to the shipped member alone. Then no code can read a tracking number from an order that hasn't shipped, and no value can be shipped and cancelled at once. Give each state a named type and build the union from them:

```typescript types
type PendingOrder = { status: "pending"; id: string };
type PaidOrder = { status: "paid"; id: string; paidAt: string };
type Order = PendingOrder | PaidOrder;
```

A transition is a function from the state it starts in to the state it leads to, like `ship(order: PaidOrder, trackingNumber: string): ShippedOrder`. Passing an order in any other state is a type error, so the rule that only paid orders ship holds everywhere `ship` is called, not just where someone remembered an `if`.

examples.code:
type FetchState =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "success"; data: string[] }
  | { status: "error"; message: string };

function render(state: FetchState): string {
  switch (state.status) {
    case "idle":
      return "Press Load to start";
    case "loading":
      return "Loading...";
    case "success":
      return `${state.data.length} items: ${state.data.join(", ")}`;
    case "error":
      return `Error: ${state.message}`;
  }
}

const states: FetchState[] = [
  { status: "idle" },
  { status: "loading" },
  { status: "success", data: ["tea", "milk", "bread"] },
  { status: "error", message: "network down" },
];

for (const state of states) {
  console.log(render(state));
}

type PendingOrder = { status: "pending"; id: string };
type PaidOrder = { status: "paid"; id: string; paidAt: string };
type ShippedOrder = { status: "shipped"; id: string; paidAt: string; trackingNumber: string };
type CancelledOrder = { status: "cancelled"; id: string; reason: string };
type Order = PendingOrder | PaidOrder | ShippedOrder | CancelledOrder;

function ship(order: PaidOrder, trackingNumber: string): ShippedOrder {
  return { ...order, status: "shipped", trackingNumber };
}

function describe(order: Order): string {
  switch (order.status) {
    case "pending":
      return `${order.id}: waiting for payment`;
    case "paid":
      return `${order.id}: paid on ${order.paidAt}`;
    case "shipped":
      return `${order.id}: shipped, tracking ${order.trackingNumber}`;
    case "cancelled":
      return `${order.id}: cancelled (${order.reason})`;
  }
}

const paid: PaidOrder = { status: "paid", id: "ord_3", paidAt: "2026-09-30" };

const orders: Order[] = [
  { status: "pending", id: "ord_1" },
  { status: "paid", id: "ord_2", paidAt: "2026-10-01" },
  ship(paid, "1Z999AA10123456784"),
  { status: "cancelled", id: "ord_4", reason: "out of stock" },
];

for (const order of orders) {
  console.log(describe(order));
}

type PendingOrder = { status: "pending"; id: string };
type PaidOrder = { status: "paid"; id: string; paidAt: string };
type ShippedOrder = { status: "shipped"; id: string; paidAt: string; trackingNumber: string };

function ship(order: PaidOrder, trackingNumber: string): ShippedOrder {
  return { ...order, status: "shipped", trackingNumber };
}

const pending: PendingOrder = { status: "pending", id: "ord_1" };
const shipped = ship(pending, "1Z999AA10123456784");
console.log(shipped.trackingNumber);

examples.explanation:
`ship` asks for a `PaidOrder`, and a pending order has no `paidAt`, so the checker refuses the call before anything runs. The order has to be paid first, through a transition of its own. An order typed as the whole union gets the same treatment. Check its `status` first: inside `if (order.status === "paid")` the checker knows it's a `PaidOrder`, so the call compiles.

```typescript harness
type PendingOrder = { status: "pending"; id: string };
type PaidOrder = { status: "paid"; id: string; paidAt: string };
type ShippedOrder = { status: "shipped"; id: string; paidAt: string; trackingNumber: string };
type Order = PendingOrder | PaidOrder;

function ship(order: PaidOrder, trackingNumber: string): ShippedOrder {
  return { ...order, status: "shipped", trackingNumber };
}

const orders: Order[] = [
  { status: "pending", id: "ord_1" },
  { status: "paid", id: "ord_2", paidAt: "2026-10-01" },
];
{{code}}
```

```typescript
for (const order of orders) {
  if (order.status === "paid") {
    console.log(ship(order, "1Z999").trackingNumber); // 1Z999
  }
}
```

