export type LabelParcel = { status: "label"; id: string; createdAt: string };
export type InTransitParcel = { status: "in_transit"; id: string; location: string };
export type DeliveredParcel = { status: "delivered"; id: string; signedBy: string };
export type Parcel = LabelParcel | InTransitParcel | DeliveredParcel;

export function summary(p: Parcel): string {
  switch (p.status) {
    case "label":
      return `${p.id}: label created on ${p.createdAt}`;
    case "in_transit":
      return `${p.id}: in transit at ${p.location}`;
    case "delivered":
      return `${p.id}: delivered, signed by ${p.signedBy}`;
  }
}

export function deliver(p: InTransitParcel, signedBy: string): DeliveredParcel {
  return { status: "delivered", id: p.id, signedBy };
}

const label: LabelParcel = { status: "label", id: "P-1042", createdAt: "2026-10-01" };
const moving: InTransitParcel = { status: "in_transit", id: "P-1042", location: "Leeds hub" };
const history: Parcel[] = [label, moving, deliver(moving, "Ana")];

for (const p of history) {
  console.log(summary(p));
}
